CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE dataset_registry(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),dataset_id TEXT UNIQUE NOT NULL,content_type TEXT NOT NULL,title TEXT NOT NULL,language TEXT NOT NULL,version TEXT NOT NULL,source_url TEXT NOT NULL,license JSONB NOT NULL,checksum TEXT,review_status TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE import_jobs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),dataset_id TEXT NOT NULL,status TEXT NOT NULL,details JSONB DEFAULT '{}',started_at TIMESTAMPTZ DEFAULT now(),completed_at TIMESTAMPTZ);
CREATE TABLE surahs(number SMALLINT PRIMARY KEY,arabic_name TEXT NOT NULL,transliterated_name TEXT NOT NULL,ayah_count SMALLINT NOT NULL CHECK(number BETWEEN 1 AND 114));
CREATE TABLE imported_quran_ayahs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),dataset_id TEXT NOT NULL,surah_number SMALLINT NOT NULL REFERENCES surahs(number),ayah_number SMALLINT NOT NULL,arabic_text TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT now(),UNIQUE(dataset_id,surah_number,ayah_number));
CREATE TABLE translation_records(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),dataset_id TEXT NOT NULL,surah_number SMALLINT NOT NULL,ayah_number SMALLINT NOT NULL,language TEXT NOT NULL,translator TEXT NOT NULL,translated_text TEXT NOT NULL,footnotes JSONB DEFAULT '[]',UNIQUE(dataset_id,surah_number,ayah_number));
CREATE TABLE tafsir_records(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),dataset_id TEXT NOT NULL,surah_number SMALLINT NOT NULL,ayah_start SMALLINT NOT NULL,ayah_end SMALLINT,language TEXT NOT NULL,commentary TEXT NOT NULL,reference TEXT NOT NULL);
CREATE TABLE hadith_records(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),dataset_id TEXT NOT NULL,collection TEXT NOT NULL,book TEXT NOT NULL,reference_code TEXT NOT NULL,arabic_text TEXT,translated_text TEXT,grading TEXT,grading_source TEXT,UNIQUE(dataset_id,reference_code));
CREATE TABLE scholar_records(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),dataset_id TEXT NOT NULL,slug TEXT NOT NULL,name TEXT NOT NULL,native_name TEXT,biography TEXT NOT NULL,languages TEXT[] DEFAULT '{}',subjects TEXT[] DEFAULT '{}',works JSONB DEFAULT '[]',UNIQUE(dataset_id,slug));
CREATE TABLE content_review_queue(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),entity_type TEXT NOT NULL,entity_id UUID,decision TEXT DEFAULT 'PENDING',reviewer TEXT,notes TEXT,created_at TIMESTAMPTZ DEFAULT now());
